mapper.select:
SELECT route_no, total_slots, base_date FROM hd_route
route_no = #{routeNo}
ORDER BY route_no

SELECT route_no, effective_from, daily_rotation, monthly_rotation, created_by, created_at FROM hd_route_rotation
route_no = #{routeNo}
ORDER BY route_no, effective_from

SELECT EXISTS (
SELECT 1 FROM hd_route_rotation
WHERE route_no = #{routeNo} AND effective_from = #{effectiveFrom}
)
